import * as React from 'react'

import './progress-ring.css'

export type ProgressRingProps = {
    /** 0–100. Leave undefined for an indeterminate spinner. */
    value?: number
    /** Accessible name, e.g. "Uploading report.pdf". */
    label: string
    /** Diameter in px. */
    size?: number
    /** Ring thickness in px. */
    thickness?: number
    /** Show the percentage in the middle. */
    showValue?: boolean
    color?: string
    className?: string
}

const ProgressRing = ({ value, label, size = 96, thickness = 8, showValue = true, color = '#a78bfa', className }: ProgressRingProps) => {
    const indeterminate = value === undefined
    const clamped = Math.min(100, Math.max(0, value ?? 0))
    const radius = 50 - thickness / 2
    const circumference = 2 * Math.PI * radius

    return <div
        role="progressbar"
        aria-label={label}
        aria-valuemin={indeterminate ? undefined : 0}
        aria-valuemax={indeterminate ? undefined : 100}
        aria-valuenow={indeterminate ? undefined : Math.round(clamped)}
        className={['rad-fx-ring', className].filter(Boolean).join(' ')}
        data-state={indeterminate ? 'indeterminate' : 'determinate'}
        style={{ width: size, height: size, '--rad-fx-ring-color': color } as React.CSSProperties}
    >
        <svg viewBox="0 0 100 100" aria-hidden="true" focusable="false">
            <circle className="rad-fx-ring-track" cx="50" cy="50" r={radius} strokeWidth={thickness} />
            <circle
                className="rad-fx-ring-bar"
                cx="50" cy="50" r={radius}
                strokeWidth={thickness}
                strokeDasharray={circumference}
                strokeDashoffset={indeterminate ? circumference * 0.7 : circumference * (1 - clamped / 100)}
            />
        </svg>
        {showValue && !indeterminate ? <span className="rad-fx-ring-value" aria-hidden="true">{Math.round(clamped)}%</span> : null}
    </div>
}

export default ProgressRing

.rad-fx-ring {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.rad-fx-ring svg {
    position: absolute;
    inset: 0;
    transform: rotate(-90deg);
}

.rad-fx-ring-track { fill: none; stroke: rgb(127, 127, 127, 0.25); }

.rad-fx-ring-bar {
    fill: none;
    stroke: var(--rad-fx-ring-color, #a78bfa);
    stroke-linecap: round;
    transition: stroke-dashoffset 600ms cubic-bezier(0.3, 0.7, 0.2, 1);
}

.rad-fx-ring[data-state='indeterminate'] svg {
    animation: rad-fx-ring-spin 1.1s linear infinite;
}

.rad-fx-ring-value {
    font-size: 0.95rem;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
}

@keyframes rad-fx-ring-spin {
    from { transform: rotate(-90deg); }
    to { transform: rotate(270deg); }
}

/* Reduced motion: progress still has to read as "working", so the spinner slows to a gentle pulse. */
@media (prefers-reduced-motion: reduce) {
    .rad-fx-ring-bar { transition: none; }
    .rad-fx-ring[data-state='indeterminate'] svg { animation: rad-fx-ring-pulse 2s ease-in-out infinite; }
}

[data-rad-fx-motion='reduce'] .rad-fx-ring-bar { transition: none; }
[data-rad-fx-motion='reduce'] .rad-fx-ring[data-state='indeterminate'] svg { animation: rad-fx-ring-pulse 2s ease-in-out infinite; }

@keyframes rad-fx-ring-pulse {
    0%, 100% { opacity: 1; transform: rotate(-90deg); }
    50% { opacity: 0.4; transform: rotate(-90deg); }
}
